#include <stdio.h>

int fish[5] = {2, 4, 6, 8, 10};

int line_find(int target) {
    int tries = 0;
    for (int i = 0; i < 5; i++) {
        tries++;
        if (fish[i] == target) {
            return tries;
        }
    }
    return -tries;
}

int half_find(int target) {
    int lo = 0;
    int hi = 4;
    int tries = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        tries++;
        if (fish[mid] == target) {
            return tries;
        } else if (fish[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -tries;
}

int main(void) {
    int targets[2] = {10, 2};
    for (int i = 0; i < 2; i++) {
        int t = targets[i];
        int a = line_find(t);
        int b = half_find(t);
        printf("找 %d：挨着看 %d 次%s，砍一半 %d 次%s\n", t,
               a < 0 ? -a : a, a < 0 ? "没找到" : "",
               b < 0 ? -b : b, b < 0 ? "没找到" : "");
    }
    return 0;
}

#include <stdio.h>

#define SLOTS 10

int shelf[SLOTS];
int used[SLOTS];

int slot_of(int id) {
    return id % SLOTS;
}

void put(int id) {
    int slot = slot_of(id);
    while (used[slot]) {
        slot = (slot + 1) % SLOTS;
    }
    shelf[slot] = id;
    used[slot] = 1;
}

int find(int id) {
    int slot = slot_of(id);
    int tries = 0;
    while (used[slot]) {
        tries++;
        if (shelf[slot] == id) {
            return tries;
        }
        slot = (slot + 1) % SLOTS;
    }
    return 0;
}

int main(void) {
    put(4);
    put(14);
    put(6);

    printf("找 14：比了 %d 次\n", find(14));
    printf("找 6：比了 %d 次\n", find(6));
    printf("找 9：比了 %d 次\n", find(9));
    return 0;
}
